    /**
     * Возвращает копию [SddsFinAiColors]. Предоставляет возможность переопределять цвета.
     */
    public fun copy(overrideColors: ColorOverrideScope.() -> Unit = {}): SddsFinAiColors {
        val colorOverrideScope = ColorOverrideScope()
        overrideColors.invoke(colorOverrideScope)
        val overrideMap = colorOverrideScope.overrideMap
        return SddsFinAiColors(colors.mapValues { overrideMap[it.key] ?: it.value })
    }

    /**
     * Возвращает копию [SddsFinAiColors]. Предоставляет возможность переопределять цвета.
     */
    internal fun copyAttrs(overrideColors: ColorAttrOverrideScope.() -> Unit = {}): SddsFinAiColors {
        val colorOverrideScope = ColorAttrOverrideScope()
        overrideColors.invoke(colorOverrideScope)
        val overrideMap = colorOverrideScope.overrideMap
        return SddsFinAiColors(colors.mapValues { colors[overrideMap[it.key]] ?: it.value })
    }
}

/**
 * Скоуп переопределения цветов
 */
public class ColorOverrideScope {
    private val _overrideMap: MutableMap<String, Color> = mutableMapOf()

    internal val overrideMap: Map<String, Color>
        get() = _overrideMap.toMap()

    /**
     * Цвет для readOnly
